INSERT INTO programs (title, description, category, icon, image_url, display_order, active) VALUES
('Education & Scholarships', 'Unlocking potential through quality learning. We provide school supplies, sponsorships, and community education to ensure every child has access to the education they deserve, breaking cycles of poverty through knowledge and opportunity.', 'core', 'BookOpen', '/lovable-uploads/52fc0a4d-9182-45f4-9a60-c30b60f58000.png', 1, true),
('Health, Sanitation & Nutrition', 'Building healthier communities from the ground up. Through maternal care, nutrition drives, clean water access, and mobile clinics, we ensure that good health is not a privilege but a right for every African.', 'core', 'Heart', '/lovable-uploads/db631d52-55f4-4b7b-b992-df3760ccf9c9.png', 2, true),
('Livelihood & Entrepreneurship', 'Empowering economic independence. We equip women, youth, and families with vocational skills and microfinance tools to start sustainable businesses, fostering self-reliance and community prosperity.', 'core', 'Briefcase', '/lovable-uploads/0bcf167f-a80f-41b6-b423-2b2b8ae3ff32.png', 3, true),
('Gender Equality & Women Empowerment', 'Championing the rights and voices of African women and girls. We create safe spaces, promote leadership opportunities, and advocate for gender equality because when women thrive, communities flourish.', 'core', 'Users', '/lovable-uploads/659d6036-65e4-4685-afbc-86153bac1d28.png', 4, true),
('Youth Leadership & Mentorship', 'Shaping tomorrow''s visionary African leaders today. Through civic education, mentorship programs, and youth camps, we nurture ethical leadership that will transform our continent.', 'core', 'Star', '/lovable-uploads/f7074fa8-f5e2-40fe-bc48-2ed3eb7f2adc.png', 5, true),
('Pan-African Culture & Awareness', 'Reviving our rich African identity and heritage. Through storytelling, arts, language preservation, and inter-community projects, we strengthen our cultural bonds and promote continental unity.', 'core', 'Globe', '/lovable-uploads/e7c03665-5121-4466-b87b-6f1707ae43f0.png', 6, true);
